import { durableRecordId } from "@ai-matrx/kit/ids";
import { createAsyncThunk } from "@reduxjs/toolkit";
import { supabase } from "../../../../host/db.js";
import { updateMessageRecord } from "../messages/messages.slice.js";
import { extractFlatText } from "../messages/messages.selectors.js";
import { saveOutputFeedback } from "../../../../host/ui-slots.js";
import {
  clearRequestEditedText,
  setRequestEditedText
} from "../active-requests/active-requests.slice.js";
import { markCacheBypass } from "./cache-bypass.slice.js";
import { invalidateConversationCache } from "./invalidate-conversation-cache.thunk.js";
import { captureError } from "../../../../host/diagnostics.js";
const editMessage = createAsyncThunk(
  "messages/editMessage",
  async ({ conversationId, messageId, newContent }, { dispatch, getState, rejectWithValue }) => {
    const prevRecord = getState().messages.byConversationId[conversationId]?.byId?.[messageId];
    if (!prevRecord) {
      console.error(
        "[editMessage] prevRecord not found",
        // access-errors: ok — dev console log for a browser-local Redux lookup; absence verified in the loaded slice
        JSON.stringify({ conversationId, messageId })
      );
      return rejectWithValue({
        // access-errors: ok — browser-local Redux lookup; the message is absent from the loaded conversation slice, no record read involved
        message: `Message ${messageId} not found in conversation ${conversationId}`
      });
    }
    if (durableRecordId(messageId) === null) {
      return rejectWithValue({
        message: "This message isn't saved yet \u2014 edit it once it finishes saving."
      });
    }
    const previousContent = prevRecord.content;
    const previousUserContent = prevRecord.userContent;
    const previousContentHistory = prevRecord.contentHistory;
    const previousStatus = prevRecord.status;
    const requestId = prevRecord._streamRequestId;
    const previousEditedText = requestId ? getState().activeRequests.byRequestId[requestId]?.editedText : null;
    const nextUserContent = prevRecord.role === "user" ? newContent : prevRecord.userContent;
    const optimisticEditedText = extractFlatText({
      ...prevRecord,
      content: newContent,
      userContent: nextUserContent
    });
    console.log(
      "[editMessage] START cid=%s mid=%s role=%s status=%s contentType=%s",
      conversationId,
      messageId,
      prevRecord.role,
      prevRecord.status,
      Array.isArray(newContent) ? "array" : typeof newContent
    );
    dispatch(
      updateMessageRecord({
        conversationId,
        messageId,
        patch: {
          content: newContent,
          userContent: nextUserContent,
          status: "edited",
          _clientStatus: "pending"
        }
      })
    );
    if (requestId) {
      dispatch(setRequestEditedText({ requestId, text: optimisticEditedText }));
    }
    const { data, error } = await supabase.rpc("cx_message_edit", {
      p_message_id: messageId,
      p_new_content: newContent
    }).returns();
    if (error) {
      dispatch(
        updateMessageRecord({
          conversationId,
          messageId,
          patch: {
            content: previousContent,
            userContent: previousUserContent,
            contentHistory: previousContentHistory,
            status: previousStatus,
            _clientStatus: "error"
          }
        })
      );
      if (requestId) {
        dispatch(
          previousEditedText === null || previousEditedText === void 0 ? clearRequestEditedText({ requestId }) : setRequestEditedText({
            requestId,
            text: previousEditedText
          })
        );
      }
      const err = error;
      const serializedError = {
        code: err.code ?? null,
        message: err.message ?? null,
        details: err.details ?? null,
        hint: err.hint ?? null,
        status: err.status ?? null,
        name: err.name ?? null
      };
      console.error(
        "[editMessage] cx_message_edit RPC failed:",
        JSON.stringify(serializedError, null, 2)
      );
      return rejectWithValue({
        message: serializedError.message ?? serializedError.details ?? serializedError.hint ?? "cx_message_edit RPC returned an error with no message"
      });
    }
    console.log(
      "[editMessage] RPC success, received row fields:",
      data && typeof data === "object" ? Object.keys(data).join(", ") : typeof data
    );
    if (data) {
      let authoritativeUserContent = data.user_content;
      if (prevRecord.role === "user" && JSON.stringify(data.user_content) !== JSON.stringify(data.content)) {
        authoritativeUserContent = data.content;
        captureError({
          source: "data-shape",
          schema: "chat",
          relation: "message",
          code: "edited-user-content-projection-mismatch",
          message: "cx_message_edit returned different content and user_content for an edited user message",
          userMessage: "Your edited message is visible here, but its saved display copy needs repair.",
          conversationId,
          callSite: "message-crud/edit-message.thunk",
          details: `messageId=${messageId}`,
          recoverable: false,
          level: "high"
        });
      }
      dispatch(
        updateMessageRecord({
          conversationId,
          messageId,
          patch: {
            content: data.content,
            userContent: authoritativeUserContent,
            contentHistory: data.content_history,
            status: data.status,
            agentId: data.agent_id,
            metadata: data.metadata,
            isVisibleToModel: data.is_visible_to_model,
            isVisibleToUser: data.is_visible_to_user,
            _clientStatus: "complete"
          }
        })
      );
      if (requestId) {
        dispatch(
          setRequestEditedText({
            requestId,
            text: extractFlatText({
              ...prevRecord,
              content: data.content,
              userContent: authoritativeUserContent
            })
          })
        );
      }
    }
    dispatch(markCacheBypass({ conversationId, conversation: true }));
    void dispatch(invalidateConversationCache({ conversationId }));
    if (prevRecord.role === "assistant") {
      void (async () => {
        try {
          const originalText = extractFlatText(prevRecord);
          const correctedText = extractFlatText({
            ...prevRecord,
            content: newContent
          });
          if (!correctedText || correctedText === originalText) return;
          await saveOutputFeedback({
            subjectType: "message",
            subjectId: messageId,
            requestId: prevRecord._streamRequestId ?? null,
            surfaceName: "chat",
            originalContent: originalText || null,
            correctedContent: correctedText,
            correctedRefType: "message",
            correctedRefId: messageId
          });
        } catch (error2) {
          console.error("[editMessage] corrected-output capture failed", error2);
        }
      })();
    }
    return { conversationId, messageId };
  }
);
export {
  editMessage
};
